uot;pagelink&quot; href=&quot;Temp-B&#226;tons-Mjra.html#REPR&#201;SENTATION&quot; title=&quot;Manuel des Joueurs R&#232;gles Avanc&#233;es : B&#226;tons&quot;&gt;de repr&#233;sentation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;26 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr  CLASS=&quot;alt&quot;&gt;&lt;td&gt;83-86&lt;/td&gt;&lt;td&gt;55-60&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-B&#226;tons-Mjra.html#TR&#201;SORS&quot; title=&quot;Manuel des Joueurs R&#232;gles Avanc&#233;es : B&#226;tons&quot;&gt;des tr&#233;sors&lt;/a&gt;&lt;/td&gt;&lt;td&gt;30 016 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;87-92&lt;/td&gt;&lt;td&gt;61-72&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-B&#226;tons-Mjra.html#SOMMEIL&quot; title=&quot;Manuel des Joueurs R&#232;gles Avanc&#233;es : B&#226;tons&quot;&gt;de sommeil&lt;/a&gt;&lt;/td&gt;&lt;td&gt;34 050 po&lt;/td&gt;&lt;/tr&gt;&lt;tr  CLASS=&quot;alt&quot;&gt;&lt;td&gt;93-95&lt;/td&gt;&lt;td&gt;73-83&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-B&#226;tons-Mjra.html#VISIONS&quot; title=&quot;Manuel des Joueurs R&#232;gles Avanc&#233;es : B&#226;tons&quot;&gt;de vision&lt;/a&gt;&lt;/td&gt;&lt;td&gt;41 250 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96-98&lt;/td&gt;&lt;td&gt;84-91&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-B&#226;tons-Mjra.html#M&#201;T&#201;O&quot; title=&quot;Manuel des Joueurs R&#232;gles Avanc&#233;es : B&#226;tons&quot;&gt;m&#233;t&#233;o&lt;/a&gt;&lt;/td&gt;&lt;td&gt;44 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr  CLASS=&quot;alt&quot;&gt;&lt;td&gt;99-100&lt;/td&gt;&lt;td&gt;92-100&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-B&#226;tons-Mjra.html#RAYONS&quot; title=&quot;Manuel des Joueurs R&#232;gles Avanc&#233;es : B&#226;tons&quot;&gt;des rayons&lt;/a&gt;&lt;/td&gt;&lt;td&gt;52 800 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
